INSERT INTO `CubeCart_email_template` VALUES(1, '1', 'Default Emails', '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">\r\n<html xmlns="http://www.w3.org/1999/xhtml">\r\n<head>\r\n<meta http-equiv="Content-Type" content="text/html; charset=UTF-8" />\r\n<meta name="viewport" content="width=device-width, initial-scale=1.0" />\r\n<style type="text/css">\r\nhtml, body, table, td {\r\n\tfont-family: Arial, Helvetica, sans-serif;\r\n\tfont-size: 14px;\r\n\tcolor: #333333;\r\n}\r\na {\r\n\tcolor: #27515d;\r\n}\r\n.w3w {\r\n\tcolor: #E11F26;\r\n\tdisplay: block;\r\n}\r\n.w3w a {\r\n\tcolor: #333333;\r\n\ttext-decoration: none;\r\n}\r\n@media only screen and (max-width: 620px) {\r\n\t.cc-email {\r\n\t\twidth: 100% !important;\r\n\t}\r\n\t.cc-email-cell {\r\n\t\tpadding-left: 16px !important;\r\n\t\tpadding-right: 16px !important;\r\n\t}\r\n}\r\n</style>\r\n<title>{$DATA.storeName}</title>\r\n<base href="{$DATA.storeURL}" />\r\n{$DATA.jsonLd}\r\n</head>\r\n<body bgcolor="#f7f7f7" style="margin:0;padding:0;background-color:#f7f7f7;">\r\n<table role="presentation" border="0" cellpadding="0" cellspacing="0" width="100%" bgcolor="#f7f7f7" style="background-color:#f7f7f7;">\r\n  <tr>\r\n    <td align="center" style="padding:24px 12px;">\r\n      <table role="presentation" class="cc-email" border="0" cellpadding="0" cellspacing="0" width="600" bgcolor="#ffffff" style="width:600px;max-width:600px;background-color:#ffffff;border-top:4px solid #27515d;border-radius:8px;">\r\n        <tr>\r\n          <td class="cc-email-cell" align="left" style="padding:24px 32px 12px 32px;text-align:left;"><a href="{$DATA.storeURL}"><img src="{$DATA.logoURL}" alt="{$DATA.storeName}" border="0" style="max-width:260px;height:auto;" /></a></td>\r\n        </tr>\r\n        <tr>\r\n          <td class="cc-email-cell" align="left" style="padding:12px 32px 24px 32px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.6;color:#333333;text-align:left;">{$EMAIL_CONTENT}</td>\r\n        </tr>\r\n        <tr>\r\n          <td class="cc-email-cell" align="left" style="padding:16px 32px 24px 32px;border-top:1px solid #e3e6e8;font-family:Arial, Helvetica, sans-serif;font-size:12px;line-height:1.6;color:#6b7479;text-align:left;"><a href="{$DATA.storeURL}" style="color:#27515d;">{$DATA.storeName}</a></td>\r\n        </tr>\r\n      </table>\r\n    </td>\r\n  </tr>\r\n</table>\r\n</body>\r\n</html>'); #EOQ
INSERT INTO `CubeCart_email_template` VALUES(2, '0', 'Default Newsletter', '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">\r\n<html xmlns="http://www.w3.org/1999/xhtml">\r\n<head>\r\n<meta http-equiv="Content-Type" content="text/html; charset=UTF-8" />\r\n<meta name="viewport" content="width=device-width, initial-scale=1.0" />\r\n<style type="text/css">\r\nhtml, body, table, td {\r\n\tfont-family: Arial, Helvetica, sans-serif;\r\n\tfont-size: 14px;\r\n\tcolor: #333333;\r\n}\r\na {\r\n\tcolor: #27515d;\r\n}\r\n.w3w {\r\n\tcolor: #E11F26;\r\n\tdisplay: block;\r\n}\r\n.w3w a {\r\n\tcolor: #333333;\r\n\ttext-decoration: none;\r\n}\r\n@media only screen and (max-width: 620px) {\r\n\t.cc-email {\r\n\t\twidth: 100% !important;\r\n\t}\r\n\t.cc-email-cell {\r\n\t\tpadding-left: 16px !important;\r\n\t\tpadding-right: 16px !important;\r\n\t}\r\n}\r\n</style>\r\n<title>{$DATA.storeName}</title>\r\n<base href="{$DATA.storeURL}" />\r\n{$DATA.jsonLd}\r\n</head>\r\n<body bgcolor="#f7f7f7" style="margin:0;padding:0;background-color:#f7f7f7;">\r\n<table role="presentation" border="0" cellpadding="0" cellspacing="0" width="100%" bgcolor="#f7f7f7" style="background-color:#f7f7f7;">\r\n  <tr>\r\n    <td align="center" style="padding:24px 12px;">\r\n      <table role="presentation" class="cc-email" border="0" cellpadding="0" cellspacing="0" width="600" bgcolor="#ffffff" style="width:600px;max-width:600px;background-color:#ffffff;border-top:4px solid #27515d;border-radius:8px;">\r\n        <tr>\r\n          <td class="cc-email-cell" align="left" style="padding:24px 32px 12px 32px;text-align:left;"><a href="{$DATA.storeURL}"><img src="{$DATA.logoURL}" alt="{$DATA.storeName}" border="0" style="max-width:260px;height:auto;" /></a></td>\r\n        </tr>\r\n        <tr>\r\n          <td class="cc-email-cell" align="left" style="padding:12px 32px 24px 32px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.6;color:#333333;text-align:left;">{$EMAIL_CONTENT}</td>\r\n        </tr>\r\n        <tr>\r\n          <td class="cc-email-cell" align="left" style="padding:16px 32px 24px 32px;border-top:1px solid #e3e6e8;font-family:Arial, Helvetica, sans-serif;font-size:12px;line-height:1.6;color:#6b7479;text-align:left;"><a href="{$DATA.storeURL}" style="color:#27515d;">{$DATA.storeName}</a><br /><br />\r\nTo unsubscribe please follow the link below:<br />\r\n<a href="{$DATA.unsubscribeURL}" style="color:#27515d;">{$DATA.unsubscribeURL}</a></td>\r\n        </tr>\r\n      </table>\r\n    </td>\r\n  </tr>\r\n</table>\r\n</body>\r\n</html>'); #EOQ
